using System;
using System.IO;
using System.Linq;
using System.Globalization;
using System.Windows.Forms;
using CircuitoStudio;
internal static class ReportSelectionTests {
 static int n;
 static void Check(bool value,string label){n++;if(!value)throw new Exception(label);}
 static void Reject(Action action,string label){bool failed=false;try{action();}catch(InvalidDataException){failed=true;}Check(failed,label);}
 [STAThread] public static int Main(){string directory=Path.Combine(Path.GetTempPath(),"report-selection-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(directory);try{
  var p=Project.CreateSample();p.Name="Projeto ç 北 <script>";p.Source.ShortCircuitKA=10;var root=p.Boards[0];var remote=new Board{Id="Q2",Name="Quadro remoto",Voltage=380};var load=new Circuit{Id="C3",Name="Carga remota",Voltage=380,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",PowerKw=6,PowerFactor=.8,CableMm2=4,LengthM=20};remote.Circuits.Add(load);p.Boards.Add(remote);var feeder=new Circuit{Id="F1",Name="Alimentador remoto",Voltage=380,Phases=PhaseMode.Trifasico,PhaseLabel="ABC",ChildBoardId="Q2",CableMm2=10,LengthM=30};root.Circuits.Add(feeder);
  root.Circuits[1].CurveStudy=new CurveStudyData{Upstream=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;1;2\n100;.1;.2","Curva omitida Ω")};root.Circuits[1].DriveMotor=new DriveMotorData{DriveReference="Inversor omitido",InputRatedA=20,OutputRatedA=20,OutputVoltageV=380,MotorReference="Motor omitido",MotorRatedA=15,MotorVoltageV=380,MotorShaftKw=5,Source="Dados de ensaio"};
  var study=Engineering.Analyze(p);var culture=CultureInfo.GetCultureInfo("pt-BR");string text=ReportSelection.Build(p,new[]{"F1"});
  Check(text.Contains("1 de 4 circuitos selecionados"),"selection scope recorded");Check(text.Contains("F1 — Alimentador remoto")&&!text.Contains("C3 — Carga remota")&&!text.Contains("C1 — Iluminação"),"only selected circuit details included");
  Check(text.Contains("Ib="+study.For(feeder).CurrentA.ToString("N3",culture)+" A"),"selected feeder retains downstream demand");Check(text.Contains("P="+study.TotalKw.ToString("N3",culture)+" kW"),"project total remains complete and labelled");Check(!text.Contains("Curva omitida")&&!text.Contains("Inversor omitido"),"curves and motor detail obey selection");
  string remoteText=ReportSelection.Build(p,new[]{"C3"});Check(remoteText.Contains("acumulada="+study.For(load).AccumulatedDropPercent.ToString("N3",culture)+"%"),"remote load retains upstream voltage drop");
  string empty=ReportSelection.Build(p,new string[0]);Check(empty.Contains("0 de 4 circuitos selecionados")&&!empty.Contains("Ib="),"empty selection produces context without circuit detail");
  Check(ReportSelection.Build(p,new[]{"F1","F1"})==text,"duplicate IDs do not duplicate report sections");Reject(delegate{ReportSelection.Build(p,new[]{"missing"});},"unknown circuit rejected");
  Check(EngineeringReport.Memory(p,study)==EngineeringReport.Memory(p,study,null),"existing complete report unchanged");
  string projectPath=Path.Combine(directory,"project.circuito");p.Save(projectPath);string before=File.ReadAllText(projectPath);
  using(var form=new ReportSelectionForm(p)){form.CreateControl();Check(form.SelectedIds.Length==4,"form opens with all circuits checked");form.SelectCircuits(new[]{"F1"});Check(form.SelectedIds.SequenceEqual(new[]{"F1"})&&form.PreviewText==text,"form preview follows explicit selection");Reject(delegate{form.SelectCircuits(new[]{"unknown"});},"invalid form selection rejected");Check(form.SelectedIds.SequenceEqual(new[]{"F1"}),"invalid selection preserves checked items");form.SelectCircuits(new string[0]);Check(form.PreviewText.Contains("0 de 4"),"form supports summary-only report");form.Size=form.MinimumSize;form.PerformLayout();var bar=form.Controls.OfType<FlowLayoutPanel>().Single();Check(bar.Controls.OfType<Button>().All(button=>button.Bottom+button.Margin.Bottom<=bar.ClientSize.Height-bar.Padding.Bottom),"report actions remain visible at minimum window size");}
  foreach(string format in new[]{"txt","rtf","html"}){string file=Path.Combine(directory,"selected."+format);ReportSelection.Save(p,new[]{"F1"},file,format);Check(new FileInfo(file).Length>0,"selected "+format+" generated");if(format=="txt")Check(File.ReadAllText(file)==text,"TXT exactly matches selected preview");if(format=="rtf")using(var control=new RichTextBox()){control.Rtf=File.ReadAllText(file);Check(control.Text.Replace("\r\n","\n").TrimEnd()==text.Replace("\r\n","\n").TrimEnd(),"RTF preserves selected text and Unicode");}if(format=="html"){string html=File.ReadAllText(file);Check(html.Contains("&lt;script&gt;")&&!html.Contains("<script>"),"HTML escapes project text");Check(!html.Contains("C3 — Carga remota"),"HTML excludes unselected details");}}
  string protectedPath=Path.Combine(directory,"selected.txt"),saved=File.ReadAllText(protectedPath);Reject(delegate{ReportSelection.Save(p,new[]{"missing"},protectedPath,"txt");},"invalid export selection rejected");Check(File.ReadAllText(protectedPath)==saved,"invalid selection preserves destination");Reject(delegate{ReportSelection.Save(p,new[]{"F1"},protectedPath,"unsupported");},"unsupported format rejected explicitly");Check(File.ReadAllText(protectedPath)==saved&&Directory.GetFiles(directory,"*.tmp").Length==0,"unsupported format leaves no temporary or overwritten file");
  p.Save(projectPath);Check(File.ReadAllText(projectPath)==before,"selection preview and exports leave project unchanged");Console.WriteLine("PASS: "+n+" report-selection assertions");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(directory,true);}}
}
